// And groups predicates with the AND operator between them.
func And(predicates ...predicate.BundleCrashEvents) predicate.BundleCrashEvents {
	return predicate.BundleCrashEvents(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.BundleCrashEvents) predicate.BundleCrashEvents {
	return predicate.BundleCrashEvents(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.BundleCrashEvents) predicate.BundleCrashEvents {
	return predicate.BundleCrashEvents(sql.NotPredicates(p))
}
